// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address caller, uint256 _value) internal {
        bool reverted;
        vm.prank(address(this));
        try c.withdraw(_value) { reverted = false; } catch { reverted = true; }
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        assertTrue((address(this) == owner) || reverted);
    }

    function testFuzz_run(address caller, uint256 _value) public {
        vm.assume(uint160(caller) > 255 && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(caller, _value);
    }

    receive() external payable { }
}
